// Repair 33 — progress-bar geometry of one month card in the recruiter's "upcoming bonuses" panel.
// Pure (no imports) so scripts/test-bonus-bar.mjs can load it. All inputs are BONUS amounts and deal
// counts — never revenue.
//   fill_counted  = counted / next
//   fill_expected = expected / next, never above 1 − fill_counted
//   fill_estimate = min(1 − counted − expected, estimateDeals × avgDealBonus / next); 0 when the estimate is null
// No next tier (top tier reached / no model): the bar is a full counted bar if anything is counted,
// else a full expected bar if anything is expected, else empty.
export type BarGeometry = { counted: number; expected: number; estimate: number }

const clamp01 = (n: number) => (Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0)

export function barGeometry(input: {
  counted: number
  expected: number
  next: number | null
  estimateDeals: number | null
  avgDealBonus: number | null
}): BarGeometry {
  const { counted, expected, next, estimateDeals, avgDealBonus } = input
  if (next == null || next <= 0) {
    if (counted > 0) return { counted: 1, expected: 0, estimate: 0 }
    return { counted: 0, expected: expected > 0 ? 1 : 0, estimate: 0 }
  }
  const fc = clamp01(counted / next)
  const fe = Math.min(clamp01(expected / next), 1 - fc)
  const est =
    estimateDeals != null && avgDealBonus != null && avgDealBonus > 0
      ? Math.min(1 - fc - fe, clamp01((estimateDeals * avgDealBonus) / next))
      : 0
  return { counted: fc, expected: fe, estimate: Math.max(0, est) }
}
